import{_ as l,a0 as p,w as s,s as i,ao as d,I as n,x as e,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"增强边缘计算的安全性 | LCTT x X-CMD","titleTemplate":false,"description":"增强边缘计算的安全性 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"增强边缘计算的安全性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"增强边缘计算的安全性 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190409 Enhanced security at the edge","title":"增强边缘计算的安全性","tag":"201904","desc":""},"relativePath":"201904/20190409 Enhanced security at the edge.md","filePath":"[post].md"}'),u={name:"201904/20190409 Enhanced security at the edge.md"};function m(T,t,f,h,g,w){const a=p("Link");return s(),i("div",null,[t[15]||(t[15]=d('<h1 id="增强边缘计算的安全性" tabindex="-1">增强边缘计算的安全性 <a class="header-anchor" href="#增强边缘计算的安全性" aria-label="Permalink to “增强边缘计算的安全性”">​</a></h1><blockquote><p>边缘计算环境带来的安全风险迫使公司必须特别关注它的安全措施。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/04/istock-1091707448-100793312-large.jpg" alt=""></p><p>说数据安全是高管们和董事会最关注的问题已经是陈词滥调了。但问题是：数据安全问题不会自己消失。</p><p>骇客和攻击者一直在寻找利用缺陷的新方法。就像公司开始使用人工智能和机器学习等新兴技术来自动化地保护他们的组织一样，那些不良分子们也在使用这些技术来达成他们的目的。</p><p>简而言之，安全问题是一定不能忽视的。现在，随着越来越多的公司开始使用边缘计算，如何保护这些边缘计算环境，需要有新的安全考量。</p><h3 id="边缘计算的风险更高" tabindex="-1">边缘计算的风险更高 <a class="header-anchor" href="#边缘计算的风险更高" aria-label="Permalink to “边缘计算的风险更高”">​</a></h3><p>正如 Network World 的一篇文章所说，边缘计算的安全架构应该将重点放在物理安全上。这并不是说要忽视保护传输过程中的数据。而是说，实际的物理环境和物理设备更加值得关注。</p><p>例如，边缘计算的硬件设备通常位于较大的公司或者广阔空间中，有时候是在很容易进入的共享办公室和公共区域里。从表面上看，这节省了成本，能更快地访问到相关的数据，而不必在后端的数据中心和前端的设备之间往返。</p><p>但是，如果没有任何级别的访问控制，这台设备就会暴露在恶意操作和简单人为错误的双重风险之下。想象一下办公室的清洁工意外地关掉了设备，以及随之而来的停机所造成的后果。</p><p>另一个风险是 “影子边缘 IT”。有时候非 IT 人员会部署一个边缘设备来快速启动项目，却没有及时通知 IT 部门这个设备正在连接到网络。例如，零售商店可能会主动安装他们自己的数字标牌，或者，销售团队会将物联网传感器应用到电视中，并在销售演示中实时地部署它们。</p><p>在这种情况下，IT 部门很少甚至完全看不到这些边缘设备，这就使得网络可能暴露在外。</p><h3 id="保护边缘计算环境" tabindex="-1">保护边缘计算环境 <a class="header-anchor" href="#保护边缘计算环境" aria-label="Permalink to “保护边缘计算环境”">​</a></h3><p>部署微型数据中心（MDC）是规避上述风险的一个简单方法。</p><blockquote><p>“在历史上，大多数这些[边缘]环境都是不受控制的，”施耐德电气安全能源部门的首席技术官和创新高级副总裁 Kevin Brown 说。“它们可能是第 1 级，但很可能是第 0 级类型的设计 —— 它们就像开放的配线柜。它们现在需要像微型数据中心一样的对待。你管理它需要像管理关键任务数据中心一样”</p></blockquote><p>单说听起来的感觉，这个解决方案是一个安全、独立的机箱，它包括在室内和室外运行程序所需的所有存储空间、处理性能和网络资源。它同样包含必要的电源、冷却、安全和管理工具。</p><p>而它最重要的是高级别的安全性。这个装置是封闭的，有上锁的门，可以防止非法入侵。通过合适的供应商，DMC 可以进行定制，包括用于远程数字化管理的监控摄像头、传感器和监控技术。</p><p>随着越来越多的公司开始利用边缘计算的优势，他们必须利用安全解决方案的优势来保护他们的数据和边缘环境。</p><p>在 APC.com 上了解保护你的边缘计算环境的最佳方案。</p><hr>',20)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),r(a,{href:"https://www.networkworld.com/article/3388130/enhanced-security-at-the-edge.html"},{default:o(()=>[...t[0]||(t[0]=[e("https://www.networkworld.com/article/3388130/enhanced-security-at-the-edge.html",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),r(a,{href:"https://www.networkworld.com/author/Anne-Taylor/"},{default:o(()=>[...t[2]||(t[2]=[e("Anne Taylor",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),r(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),r(a,{href:"https://github.com/hopefully2333"},{default:o(()=>[...t[4]||(t[4]=[e("hopefully2333",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),r(a,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const b=l(u,[["render",m]]);export{x as __pageData,b as default};
